#!/usr/bin/env python3
"""ArtIN3D: compara o tempo de fatiamento de duas compilações do OrcaSlicer.

Uso: bench.py <app_normal> <app_lto> <saida_dir>
Cada app é o caminho do OrcaSlicer.app. As rodadas alternam a ordem das
duas compilações para que aquecimento e cache do disco não favoreçam nenhuma.
"""
import hashlib, json, os, statistics, subprocess, sys, tempfile, time

RUNS = 5

PROFILES = 'Contents/Resources/profiles/Elegoo'
MACHINE = f'{PROFILES}/machine/ECC2/Elegoo Centauri Carbon 2 0.4 nozzle.json'
PROCESS = f'{PROFILES}/process/ECC2/0.20mm Standard @Elegoo CC2 0.4 nozzle.json'
FILAMENT = f'{PROFILES}/filament/ECC2/Elegoo PLA @ECC2.json'

SCENARIOS = [
    ('Benchy', 'Contents/Resources/handy_models/3DBenchy.drc', []),
    ('Coelho 2,5x', 'Contents/Resources/handy_models/Stanford_Bunny.drc', ['--scale', '2.5']),
]


def slice_once(app, model, extra, out_dir):
    binary = os.path.join(app, 'Contents/MacOS/OrcaSlicer')
    os.makedirs(out_dir, exist_ok=True)
    with tempfile.TemporaryDirectory() as datadir:
        cmd = [binary, '--datadir', datadir,
               '--load-settings', f'{os.path.join(app, MACHINE)};{os.path.join(app, PROCESS)}',
               '--load-filaments', os.path.join(app, FILAMENT),
               '--arrange', '1', *extra,
               '--slice', '0', '--outputdir', out_dir, os.path.join(app, model)]
        start = time.perf_counter()
        res = subprocess.run(cmd, capture_output=True, text=True)
        elapsed = time.perf_counter() - start
    if res.returncode != 0:
        sys.stderr.write(f'Falhou ({res.returncode}): {" ".join(cmd)}\n{res.stdout[-3000:]}\n{res.stderr[-3000:]}\n')
        raise SystemExit(1)
    return elapsed


def gcode_hash(out_dir):
    """Hash do G-code sem as linhas que mudam a cada execução (data, versão, tempo de fatiamento)."""
    files = sorted(f for f in os.listdir(out_dir) if f.endswith('.gcode'))
    if not files:
        raise SystemExit(f'Nenhum G-code em {out_dir}')
    h = hashlib.sha256()
    with open(os.path.join(out_dir, files[0]), errors='replace') as f:
        for line in f:
            low = line.lower()
            if line.startswith(';') and ('generated by' in low or 'date' in low or 'time' in low):
                continue
            h.update(line.encode())
    return h.hexdigest()


def main():
    apps = {'normal': sys.argv[1], 'lto': sys.argv[2]}
    out_root = sys.argv[3]
    results = {}
    for name, model, extra in SCENARIOS:
        times = {k: [] for k in apps}
        hashes = {}
        for variant, app in apps.items():  # aquecimento, não entra na média
            out = os.path.join(out_root, f'{name}-{variant}-warmup')
            slice_once(app, model, extra, out)
            hashes[variant] = gcode_hash(out)
        for i in range(RUNS):
            order = list(apps) if i % 2 == 0 else list(reversed(apps))
            for variant in order:
                out = os.path.join(out_root, f'{name}-{variant}-{i}')
                times[variant].append(slice_once(apps[variant], model, extra, out))
        med = {k: statistics.median(v) for k, v in times.items()}
        results[name] = {'tempos': times, 'mediana': med,
                         'ganho_pct': 100 * (med['normal'] - med['lto']) / med['normal'],
                         'gcode_igual': hashes['normal'] == hashes['lto']}
        print(name, json.dumps(results[name]), flush=True)

    with open(os.path.join(out_root, 'resultado.json'), 'w') as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
    lines = ['| Modelo | Normal (s) | LTO (s) | Ganho | G-code igual |', '|---|---|---|---|---|']
    for name, r in results.items():
        lines.append(f"| {name} | {r['mediana']['normal']:.2f} | {r['mediana']['lto']:.2f} | "
                     f"{r['ganho_pct']:+.1f}% | {'sim' if r['gcode_igual'] else 'NÃO'} |")
    table = '\n'.join(lines)
    print(table)
    summary = os.environ.get('GITHUB_STEP_SUMMARY')
    if summary:
        with open(summary, 'a') as f:
            f.write(f'## Teste de LTO (mediana de {RUNS} rodadas)\n\n{table}\n')


if __name__ == '__main__':
    main()
